#include "LmsRepository.h"
#include "LatePenaltyStrategy.h"
#include <sqlite3.h>
#include <stdexcept>
#include <string>
#include <iostream>
#include <cstdio>
#include <ctime>
#include <algorithm>
using namespace std;
namespace {
void check(sqlite3* db,int rc,sqlite3_stmt* st,const string& what){ if(rc!=SQLITE_DONE){string e=sqlite3_errmsg(db); if(st)sqlite3_finalize(st); throw runtime_error(what+": "+e);} }
sqlite3_stmt* prep(sqlite3* db,const char* sql){sqlite3_stmt* s=nullptr; if(sqlite3_prepare_v2(db,sql,-1,&s,nullptr)!=SQLITE_OK)throw runtime_error(sqlite3_errmsg(db)); return s;}
void txt(sqlite3_stmt*s,int i,const string&v){sqlite3_bind_text(s,i,v.c_str(),-1,SQLITE_TRANSIENT);}
}
int LmsRepository::ensureDemoDepartment(){auto db=database.getConnection();auto st=prep(db,"SELECT MIN(department_id) FROM Departments;");int rc=sqlite3_step(st);int id=rc==SQLITE_ROW?sqlite3_column_int(st,0):0;sqlite3_finalize(st);if(id>0)return id;return createDepartment("General Studies");}
int LmsRepository::createDepartment(const string& name){if(name.empty())throw invalid_argument("Department name required."); auto db=database.getConnection(); auto s=prep(db,"INSERT INTO Departments(department_name) VALUES(?);"); txt(s,1,name); int rc=sqlite3_step(s); check(db,rc,s,"Create department failed"); int id=(int)sqlite3_last_insert_rowid(db);sqlite3_finalize(s);return id;}
int LmsRepository::createCourse(const string& code,const string& name,int dept){if(code.empty()||name.empty()||dept<=0)throw invalid_argument("Course code, name and valid department ID are required.");auto db=database.getConnection();auto s=prep(db,"INSERT INTO Courses(course_code,course_name,department_id) VALUES(?,?,?);");txt(s,1,code);txt(s,2,name);sqlite3_bind_int(s,3,dept);int rc=sqlite3_step(s);check(db,rc,s,"Create course failed");int id=(int)sqlite3_last_insert_rowid(db);sqlite3_finalize(s);return id;}
int LmsRepository::createAssignment(int course,int lecturer,const string& title,const string& deadline,double max){if(course<=0||lecturer<=0||title.empty()||deadline.empty()||max<=0)throw invalid_argument("Course, lecturer, title, deadline and positive maximum mark are required.");auto db=database.getConnection();auto checkAssignment=prep(db,"SELECT 1 FROM CourseLecturers WHERE course_id=? AND lecturer_id=?;");sqlite3_bind_int(checkAssignment,1,course);sqlite3_bind_int(checkAssignment,2,lecturer);int assigned=sqlite3_step(checkAssignment);sqlite3_finalize(checkAssignment);if(assigned!=SQLITE_ROW)throw runtime_error("This lecturer must be assigned to the course by the administrator first.");auto s=prep(db,"INSERT INTO Assignments(course_id,lecturer_id,title,description,deadline,max_mark,resubmission_limit) VALUES(?,?,?, '',?,?,1);");sqlite3_bind_int(s,1,course);sqlite3_bind_int(s,2,lecturer);txt(s,3,title);txt(s,4,deadline);sqlite3_bind_double(s,5,max);int rc=sqlite3_step(s);check(db,rc,s,"Create assignment failed");int id=(int)sqlite3_last_insert_rowid(db);sqlite3_finalize(s);return id;}
void LmsRepository::assignLecturer(int lecturer,int course){if(lecturer<=0||course<=0)throw invalid_argument("Valid lecturer and course IDs are required.");auto db=database.getConnection();auto s=prep(db,"INSERT INTO CourseLecturers(lecturer_id,course_id) SELECT ?,? WHERE EXISTS(SELECT 1 FROM Users WHERE user_id=? AND role='Lecturer') AND EXISTS(SELECT 1 FROM Courses WHERE course_id=?);");sqlite3_bind_int(s,1,lecturer);sqlite3_bind_int(s,2,course);sqlite3_bind_int(s,3,lecturer);sqlite3_bind_int(s,4,course);int rc=sqlite3_step(s);check(db,rc,s,"Assign lecturer failed");int n=sqlite3_changes(db);sqlite3_finalize(s);if(!n)throw runtime_error("Lecturer or course does not exist, or this assignment already exists.");}
void LmsRepository::listStudentCoursesAndAssignments(int student){auto db=database.getConnection();auto s=prep(db,"SELECT c.course_code,c.course_name,a.assignment_id,a.title,a.deadline,a.max_mark FROM CourseEnrolments e JOIN Courses c ON c.course_id=e.course_id LEFT JOIN Assignments a ON a.course_id=c.course_id WHERE e.student_id=? ORDER BY c.course_code,a.assignment_id;");sqlite3_bind_int(s,1,student);cout<<"Course code | Course | Assignment ID | Assignment | Deadline | Maximum mark\n";while(sqlite3_step(s)==SQLITE_ROW){for(int i=0;i<6;i++){if(i)printf(" | ");const unsigned char*v=sqlite3_column_text(s,i);printf("%s",v?(const char*)v:"NULL");}printf("\n");}sqlite3_finalize(s);}
void LmsRepository::enrolStudent(int student,int course){if(student<=0||course<=0)throw invalid_argument("Valid student and course IDs are required.");auto db=database.getConnection();auto s=prep(db,"INSERT INTO CourseEnrolments(student_id,course_id) SELECT ?,? WHERE EXISTS(SELECT 1 FROM Users WHERE user_id=? AND role='Student') AND EXISTS(SELECT 1 FROM Courses WHERE course_id=?);");sqlite3_bind_int(s,1,student);sqlite3_bind_int(s,2,course);sqlite3_bind_int(s,3,student);sqlite3_bind_int(s,4,course);int rc=sqlite3_step(s);check(db,rc,s,"Enrolment failed");int n=sqlite3_changes(db);sqlite3_finalize(s);if(!n)throw runtime_error("Student or course does not exist, or enrolment already exists.");}
int LmsRepository::submitAssignment(int assignment,int student,const string& content,const string& at){if(assignment<=0||student<=0||content.empty()||at.empty())throw invalid_argument("Assignment, student, content and timestamp are required.");auto db=database.getConnection();auto s=prep(db,"SELECT deadline,COALESCE((SELECT revised_deadline FROM Extensions WHERE assignment_id=? AND student_id=? AND approved=1),deadline) FROM Assignments WHERE assignment_id=? AND EXISTS(SELECT 1 FROM CourseEnrolments WHERE course_id=Assignments.course_id AND student_id=?);");sqlite3_bind_int(s,1,assignment);sqlite3_bind_int(s,2,student);sqlite3_bind_int(s,3,assignment);sqlite3_bind_int(s,4,student);int rc=sqlite3_step(s);if(rc!=SQLITE_ROW){sqlite3_finalize(s);throw runtime_error("Assignment not found or student is not enrolled in its course.");}string deadline=(const char*)sqlite3_column_text(s,1);sqlite3_finalize(s);string status=at<=deadline?"Submitted":"Late";
 s=prep(db,"SELECT COALESCE(MAX(attempt_no),0) FROM Submissions WHERE assignment_id=? AND student_id=?;");sqlite3_bind_int(s,1,assignment);sqlite3_bind_int(s,2,student);rc=sqlite3_step(s);int attempt=rc==SQLITE_ROW?sqlite3_column_int(s,0)+1:1;sqlite3_finalize(s);if(attempt>2)throw runtime_error("Resubmission limit reached (one resubmission allowed).");if(attempt==2 && at.size()>=10 && deadline.size()>=10 && at.substr(0,10)>deadline.substr(0,10))throw runtime_error("Resubmission is allowed only on or before the effective deadline.");
 s=prep(db,"INSERT INTO Submissions(assignment_id,student_id,attempt_no,submitted_at,submission_content,status) VALUES(?,?,?,?,?,?);");sqlite3_bind_int(s,1,assignment);sqlite3_bind_int(s,2,student);sqlite3_bind_int(s,3,attempt);txt(s,4,at);txt(s,5,content);txt(s,6,status);rc=sqlite3_step(s);check(db,rc,s,"Submission failed");int id=(int)sqlite3_last_insert_rowid(db);sqlite3_finalize(s);return id;}
void LmsRepository::listTable(const string& table){const char* sql=nullptr;if(table=="Users")sql="SELECT user_id,username,name,email,role FROM Users ORDER BY user_id";else if(table=="Departments")sql="SELECT department_id,department_name FROM Departments ORDER BY department_id";else if(table=="Courses")sql="SELECT course_id,course_code,course_name,department_id FROM Courses ORDER BY course_id";else if(table=="Assignments")sql="SELECT assignment_id,course_id,lecturer_id,title,deadline,max_mark FROM Assignments ORDER BY assignment_id";else if(table=="Submissions")sql="SELECT submission_id,assignment_id,student_id,attempt_no,submitted_at,status FROM Submissions ORDER BY submission_id";else if(table=="Marks")sql="SELECT mark_id,submission_id,score,feedback,moderation_status,released_at FROM Marks ORDER BY mark_id";else if(table=="AuditRecords")sql="SELECT audit_id,mark_id,changed_by,changed_at,old_value,new_value,reason FROM AuditRecords ORDER BY audit_id";else throw invalid_argument("Unsupported listing.");auto db=database.getConnection();auto s=prep(db,sql);int cols=sqlite3_column_count(s);while(sqlite3_step(s)==SQLITE_ROW){for(int i=0;i<cols;i++){if(i)printf(" | ");const unsigned char*v=sqlite3_column_text(s,i);printf("%s",v?(const char*)v:"NULL");}printf("\n");}sqlite3_finalize(s);}
void LmsRepository::markSubmission(int submission,int lecturer,double score,const string& feedback,const string& reason){if(score<0||feedback.empty()||reason.empty())throw invalid_argument("Score must be non-negative; feedback and audit reason are required.");auto db=database.getConnection();auto s=prep(db,"SELECT a.max_mark, s.submitted_at, COALESCE((SELECT revised_deadline FROM Extensions e WHERE e.assignment_id=a.assignment_id AND e.student_id=s.student_id AND e.approved=1),a.deadline) FROM Submissions s JOIN Assignments a ON a.assignment_id=s.assignment_id WHERE s.submission_id=? AND a.lecturer_id=?;");sqlite3_bind_int(s,1,submission);sqlite3_bind_int(s,2,lecturer);int rc=sqlite3_step(s);if(rc!=SQLITE_ROW){sqlite3_finalize(s);throw runtime_error("Submission not found or assignment is not owned by this lecturer.");}double maxMark=sqlite3_column_double(s,0);string submitted=(const char*)sqlite3_column_text(s,1);string deadline=(const char*)sqlite3_column_text(s,2);sqlite3_finalize(s);if(score>maxMark)throw invalid_argument("Score cannot exceed assignment maximum.");
 // Late penalty: deduct 10% of maximum mark per calendar day late, capped at three days; later work receives zero.
 if(submitted.size()>=10 && deadline.size()>=10 && submitted.substr(0,10)>deadline.substr(0,10)) {
   auto days=[](const string& d)->long long { std::tm tm{}; tm.tm_year=stoi(d.substr(0,4))-1900; tm.tm_mon=stoi(d.substr(5,2))-1; tm.tm_mday=stoi(d.substr(8,2)); tm.tm_isdst=-1; return (long long)(std::mktime(&tm)/86400); };
   long long lateDays=days(submitted)-days(deadline);
   StandardLatePenaltyStrategy strategy;
   score = strategy.apply(score, maxMark, lateDays);
 }
 s=prep(db,"BEGIN IMMEDIATE;");rc=sqlite3_step(s);sqlite3_finalize(s);if(rc!=SQLITE_DONE)throw runtime_error(sqlite3_errmsg(db));
 try{s=prep(db,"SELECT mark_id,score FROM Marks WHERE submission_id=?;");sqlite3_bind_int(s,1,submission);rc=sqlite3_step(s);int markId=0;bool oldNull=true;double old=0;if(rc==SQLITE_ROW){markId=sqlite3_column_int(s,0);oldNull=sqlite3_column_type(s,1)==SQLITE_NULL;old=sqlite3_column_double(s,1);}sqlite3_finalize(s);
 if(!markId){s=prep(db,"INSERT INTO Marks(submission_id,score,feedback,moderation_status,marked_by,marked_at) VALUES(?,?,?,'Pending',?,CURRENT_TIMESTAMP);");sqlite3_bind_int(s,1,submission);sqlite3_bind_double(s,2,score);txt(s,3,feedback);sqlite3_bind_int(s,4,lecturer);}else{s=prep(db,"UPDATE Marks SET score=?,feedback=?,moderation_status='Pending',marked_by=?,marked_at=CURRENT_TIMESTAMP WHERE mark_id=?;");sqlite3_bind_double(s,1,score);txt(s,2,feedback);sqlite3_bind_int(s,3,lecturer);sqlite3_bind_int(s,4,markId);}rc=sqlite3_step(s);check(db,rc,s,"Save mark failed");sqlite3_finalize(s);if(!markId)markId=(int)sqlite3_last_insert_rowid(db);
 s=prep(db,"INSERT INTO AuditRecords(mark_id,changed_by,old_value,new_value,reason) VALUES(?,?,?,?,?);");sqlite3_bind_int(s,1,markId);sqlite3_bind_int(s,2,lecturer);if(oldNull)sqlite3_bind_null(s,3);else sqlite3_bind_double(s,3,old);sqlite3_bind_double(s,4,score);txt(s,5,reason);rc=sqlite3_step(s);check(db,rc,s,"Audit mark change failed");sqlite3_finalize(s);
 s=prep(db,"UPDATE Submissions SET status='Marked' WHERE submission_id=?;");sqlite3_bind_int(s,1,submission);rc=sqlite3_step(s);check(db,rc,s,"Update submission status failed");sqlite3_finalize(s);s=prep(db,"COMMIT;");rc=sqlite3_step(s);sqlite3_finalize(s);if(rc!=SQLITE_DONE)throw runtime_error(sqlite3_errmsg(db));}catch(...){sqlite3_exec(db,"ROLLBACK;",nullptr,nullptr,nullptr);throw;}}
void LmsRepository::moderateMark(int mark,int hod,bool approve,const string& reason){if(reason.empty())throw invalid_argument("Moderation reason required.");auto db=database.getConnection();auto s=prep(db,"UPDATE Marks SET moderation_status=?,moderated_by=?,moderated_at=CURRENT_TIMESTAMP WHERE mark_id=? AND released_at IS NULL AND EXISTS(SELECT 1 FROM Submissions s JOIN Assignments a ON a.assignment_id=s.assignment_id JOIN Courses c ON c.course_id=a.course_id JOIN Users h ON h.user_id=? AND h.department_id=c.department_id WHERE s.submission_id=Marks.submission_id);");txt(s,1,approve?"Approved":"Rejected");sqlite3_bind_int(s,2,hod);sqlite3_bind_int(s,3,mark);sqlite3_bind_int(s,4,hod);int rc=sqlite3_step(s);check(db,rc,s,"Moderation failed");int n=sqlite3_changes(db);sqlite3_finalize(s);if(!n)throw runtime_error("Mark not found or already released.");s=prep(db,"UPDATE Submissions SET status=? WHERE submission_id=(SELECT submission_id FROM Marks WHERE mark_id=?);");txt(s,1,approve?"Moderated":"Marked");sqlite3_bind_int(s,2,mark);rc=sqlite3_step(s);check(db,rc,s,"Update moderation status failed");sqlite3_finalize(s);}
void LmsRepository::releaseMark(int mark,int hod){(void)hod;auto db=database.getConnection();auto s=prep(db,"UPDATE Marks SET released_at=CURRENT_TIMESTAMP WHERE mark_id=? AND moderation_status='Approved' AND released_at IS NULL AND EXISTS(SELECT 1 FROM Submissions s JOIN Assignments a ON a.assignment_id=s.assignment_id JOIN Courses c ON c.course_id=a.course_id JOIN Users h ON h.user_id=? AND h.department_id=c.department_id WHERE s.submission_id=Marks.submission_id);");sqlite3_bind_int(s,1,mark);sqlite3_bind_int(s,2,hod);int rc=sqlite3_step(s);check(db,rc,s,"Release mark failed");int n=sqlite3_changes(db);sqlite3_finalize(s);if(!n)throw runtime_error("Only an approved, unreleased mark can be released.");s=prep(db,"UPDATE Submissions SET status='Released' WHERE submission_id=(SELECT submission_id FROM Marks WHERE mark_id=?);");sqlite3_bind_int(s,1,mark);rc=sqlite3_step(s);check(db,rc,s,"Update release status failed");sqlite3_finalize(s);}
void LmsRepository::grantExtension(int assignment,int student,const string& deadline,const string& reason,int approver){if(deadline.empty()||reason.empty())throw invalid_argument("Revised deadline and reason required.");auto db=database.getConnection();auto s=prep(db,"INSERT INTO Extensions(assignment_id,student_id,revised_deadline,reason,approved,approved_by,approved_at) VALUES(?,?, ?, ?,1,?,CURRENT_TIMESTAMP) ON CONFLICT(assignment_id,student_id) DO UPDATE SET revised_deadline=excluded.revised_deadline,reason=excluded.reason,approved=1,approved_by=excluded.approved_by,approved_at=CURRENT_TIMESTAMP;");sqlite3_bind_int(s,1,assignment);sqlite3_bind_int(s,2,student);txt(s,3,deadline);txt(s,4,reason);sqlite3_bind_int(s,5,approver);int rc=sqlite3_step(s);check(db,rc,s,"Grant extension failed");sqlite3_finalize(s);}

void LmsRepository::listReleasedMarksForStudent(int studentId) {
    auto db=database.getConnection(); auto st=prep(db,
      "SELECT m.mark_id,s.submission_id,a.title,m.score,m.feedback,m.released_at FROM Marks m JOIN Submissions s ON s.submission_id=m.submission_id JOIN Assignments a ON a.assignment_id=s.assignment_id WHERE s.student_id=? AND m.released_at IS NOT NULL ORDER BY m.mark_id;");
    sqlite3_bind_int(st,1,studentId); cout << "Mark ID | Submission ID | Assignment | Score | Feedback | Released at\n";
    while(sqlite3_step(st)==SQLITE_ROW){for(int i=0;i<6;i++){if(i)printf(" | ");const unsigned char*v=sqlite3_column_text(st,i);printf("%s",v?(const char*)v:"NULL");}printf("\n");}sqlite3_finalize(st);
}

void LmsRepository::listDepartmentMarks(int hodId) {
    auto db=database.getConnection(); auto st=prep(db,
      "SELECT m.mark_id,s.submission_id,a.title,m.score,m.feedback,m.moderation_status,m.released_at FROM Marks m JOIN Submissions s ON s.submission_id=m.submission_id JOIN Assignments a ON a.assignment_id=s.assignment_id JOIN Courses c ON c.course_id=a.course_id JOIN Users h ON h.user_id=? AND h.department_id=c.department_id ORDER BY m.mark_id;");
    sqlite3_bind_int(st,1,hodId); cout << "Mark ID | Submission ID | Assignment | Score | Feedback | Moderation | Released at\n";
    while(sqlite3_step(st)==SQLITE_ROW){for(int i=0;i<7;i++){if(i)printf(" | ");const unsigned char*v=sqlite3_column_text(st,i);printf("%s",v?(const char*)v:"NULL");}printf("\n");}sqlite3_finalize(st);
}
